{
  "items": [
    {
      "name": "AkraBazziRecurrence.GrowsPolynomially.eventually_atTop_ge",
      "module_name": "Mathlib.Computability.AkraBazzi.GrowsPolynomially",
      "kind": "theorem",
      "type": "∀ {f : ℝ → ℝ} {b : ℝ},\n  b ∈ Set.Ioo 0 1 →\n    AkraBazziRecurrence.GrowsPolynomially f →\n      ∃ c > 0, ∀ᶠ (x : ℝ) in Filter.atTop, ∀ u ∈ Set.Icc (b * x) x, c * f x ≤ f u"
    },
    {
      "name": "tendsto_bdd_div_atTop_nhds_zero",
      "module_name": "Mathlib.Topology.Algebra.Order.Field",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {α : Type u_2} [inst : Field 𝕜] [inst_1 : LinearOrder 𝕜] [IsStrictOrderedRing 𝕜]\n  [inst_3 : TopologicalSpace 𝕜] [OrderTopology 𝕜] {l : Filter α} {f g : α → 𝕜} {b B : 𝕜},\n  (∀ᶠ (x : α) in l, b ≤ f x) →\n    (∀ᶠ (x : α) in l, f x ≤ B) → Filter.Tendsto g l Filter.atTop → Filter.Tendsto (fun x => f x / g x) l (nhds 0)"
    },
    {
      "name": "AkraBazziRecurrence.eventually_asympBound_r_pos",
      "module_name": "Mathlib.Computability.AkraBazzi.SumTransform",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Fintype α] {T : ℕ → ℝ} {g : ℝ → ℝ} {a b : α → ℝ} {r : α → ℕ → ℕ} [inst_1 : Nonempty α]\n  (R : AkraBazziRecurrence T g a b r),\n  ∀ᶠ (n : ℕ) in Filter.atTop, ∀ (i : α), 0 < AkraBazziRecurrence.asympBound g a b (r i n)"
    },
    {
      "name": "AkraBazziRecurrence.eventually_one_sub_smoothingFn_pos_real",
      "module_name": "Mathlib.Computability.AkraBazzi.SumTransform",
      "kind": "theorem",
      "type": "∀ᶠ (x : ℝ) in Filter.atTop, 0 < 1 - AkraBazziRecurrence.smoothingFn x"
    },
    {
      "name": "Filter.eventually_lt_add_pos_of_limsup_le",
      "module_name": "Mathlib.Order.LiminfLimsup",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : ConditionallyCompleteLinearOrder α] [inst_1 : Preorder β]\n  [inst_2 : AddZeroClass α] [AddLeftStrictMono α] {x ε : α} {u : β → α},\n  Filter.IsBoundedUnder LE.le Filter.atTop u →\n    Filter.limsup u Filter.atTop ≤ x → 0 < ε → ∀ᶠ (b : β) in Filter.atTop, u b < x + ε"
    },
    {
      "name": "LinearGrowth.linearGrowthSup_le_iff",
      "module_name": "Mathlib.Analysis.Asymptotics.LinearGrowth",
      "kind": "theorem",
      "type": "∀ {u : ℕ → EReal} {a : EReal}, LinearGrowth.linearGrowthSup u ≤ a ↔ ∀ b > a, ∀ᶠ (n : ℕ) in Filter.atTop, u n ≤ b * ↑n"
    },
    {
      "name": "Filter.Tendsto.num_atTop_iff_den_atTop",
      "module_name": "Mathlib.Analysis.SpecificLimits.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_4} {K : Type u_5} [inst : Field K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K]\n  [inst_3 : TopologicalSpace K] [OrderTopology K] [ContinuousInv K] {f g : α → K} {l : Filter α} {a : K},\n  0 < a →\n    Filter.Tendsto (fun x => f x / g x) l (nhds a) → (Filter.Tendsto f l Filter.atTop ↔ Filter.Tendsto g l Filter.atTop)"
    },
    {
      "name": "AkraBazziRecurrence.GrowsPolynomially.eventually_atTop_nonneg_or_nonpos",
      "module_name": "Mathlib.Computability.AkraBazzi.GrowsPolynomially",
      "kind": "theorem",
      "type": "∀ {f : ℝ → ℝ},\n  AkraBazziRecurrence.GrowsPolynomially f → (∀ᶠ (x : ℝ) in Filter.atTop, 0 ≤ f x) ∨ ∀ᶠ (x : ℝ) in Filter.atTop, f x ≤ 0"
    }
  ]
}
